package com.aliothmoon.maafw.once;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;
import static org.junit.Assert.*;
/** Pure helpers/source contracts; no Activity, Binder, Maa engine, Android lifecycle or live root execution. */
public class RootRuntimeContractTest {
 private String source(String name)throws Exception{Path p=Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/"+name);if(!Files.exists(p))p=Path.of(System.getProperty("working.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/"+name);return Files.readString(p);}
 @Test public void postcheckQuarantineCannotReleaseEarlierCleanResources(){AtomicBoolean clean=new AtomicBoolean(true);boolean prior=clean.get();clean.set(false);assertFalse(CaptureSessionRuntime.rootResourcesAfterPostcheck(prior,clean::get));assertFalse(CaptureSessionRuntime.rootResourcesAfterPostcheck(true,()->{throw new SecurityException("unknown");}));assertTrue(CaptureSessionRuntime.rootResourcesAfterPostcheck(true,()->true));assertFalse(CaptureSessionRuntime.rootResourcesAfterPostcheck(false,()->true));}
 @Test public void productionRechecksAfterPostIpcEvenIfItThrows()throws Exception{String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("try{rootPreflightSourceConfirmed=acceptRootSourcePostcheck();}"));assertTrue(s.contains("finally{resources=rootResourcesAfterPostcheck(resources,()->rootResourcesClosed(result));}"));assertTrue(s.indexOf("finally{resources=rootResourcesAfterPostcheck")<s.indexOf("released=resources;rootCandidate"));assertTrue(s.contains("!ReviewBingNavigation.knownClean()"));}
 @Test public void firstBusinessCommonAndMaximumReceiptFitsCommitBudget(){String common="source=REAL_ROOT_NATIVE mode=BUSINESS phase=FIRST\n"+"candidate=TARGET_READY ".repeat(70)+"tapKind=DISPATCHED returnReady=true";String diag="rootCleanup=CONFIRMED nativeCleanup=CONFIRMED nativeMemory=WIPED "+"rowGate=PASS ".repeat(100)+"terminalReason=RETURN_READY";String text=CaptureSessionRuntime.rootReceiptText(common,diag);assertTrue(text.length()<=8192);assertTrue(text.contains("returnReady=true"));assertTrue(text.contains("terminalReason=RETURN_READY"));String worst=CaptureSessionRuntime.rootReceiptText("x".repeat(30000)+"FIRST_TAIL","FIRST_GATE "+"y".repeat(30000)+"CLEANUP_TAIL");assertEquals(8001,worst.length());assertTrue(worst.contains("FIRST_GATE"));assertTrue(worst.endsWith("CLEANUP_TAIL"));}
 @Test public void diagnosticsDoNotReviveInvalidPageCandidate()throws Exception{String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("if(rootPreflightValid){"));assertTrue(s.contains("if(seriesIntent==null&&!RootFamilyDiagnosticProfile.ACTIVE&&released&&completedDiagnostics!=null)details+="));assertFalse(CaptureSessionRuntime.rootPreflightPage(null));}
 @Test public void preflightCannotConstructBusinessRun()throws Exception{String s=source("DormantCaptureConfirmationActivity.java"),r=source("CaptureSessionRuntime.java");assertTrue(s.contains("autonomousRun=mode==RootCaptureScope.Mode.BUSINESS?NativeAutonomousCardRun.confirmed(this):null"));assertTrue(r.contains("Preflight must not construct a business run"));assertTrue(r.contains("ReadOnlyTwoStageRun.Capture.moreFamilyDiagnostic("));assertFalse(r.contains("new ReadOnlyTwoStageRun("));}
 @Test public void directSecondUsesContinuationWithoutRestoreOrSyntheticClick()throws Exception{String s=source("DormantCaptureConfirmationActivity.java");String block=s.substring(s.indexOf("}else if(exact.rootPhase()==RootCaptureScope.Phase.FIRST"),s.indexOf("RootCaptureUi.status(this,rootHistory"));assertTrue(block.contains("claimOpaqueContinuation"));assertTrue(block.contains("RootCaptureScope.Phase.SECOND,continuation,autonomousRun"));assertFalse(block.contains("new LiveClick("));assertFalse(block.contains("moveToFront("));assertFalse(block.contains("restoreOwnTaskForRootDisplay("));assertTrue(block.indexOf("CaptureSessionRuntime.startRoot")<block.indexOf("return;"));}
 @Test public void rootDoesNotBorrowProjectionOrFgsEvidence()throws Exception{String r=source("CaptureSessionRuntime.java");String root=r.substring(r.indexOf("static CaptureSessionRuntime startRoot("),r.indexOf("static final class RootPublication"));assertFalse(root.contains("ProjectionTicket"));assertFalse(root.contains("finishForeground"));assertFalse(root.contains("confirmedDestruction"));assertTrue(root.contains("RealCaptureClaim.consume(grant,EPOCH,requestOwner"));assertTrue(root.contains("rootBinding.cleanReceipt()"));assertTrue(root.contains("rootCleanReceipt.liveTransport()"));}
 @Test public void localSourceGateDoesNotReadMetadataOrPerformBinder()throws Exception{String r=source("CaptureSessionRuntime.java");String block=r.substring(r.indexOf("private void rootSourceGate()"),r.indexOf("private void rootNavigationRevoked()"));assertTrue(block.contains("rootHiddenScalar()"));assertFalse(block.contains("hiddenWithSoleTask"));assertFalse(block.contains(".read("));assertFalse(block.contains("getTask"));}
 @Test public void currentRootEntryAndEpochSurviveBusinessAcceptUntilKnownClosed()throws Exception{String r=source("CaptureSessionRuntime.java");String block=r.substring(r.indexOf("private void closeRootOnOwner()"),r.indexOf("boolean rootPublicationCurrent()"));assertTrue(block.indexOf("autonomousRun.acceptAfterCleanup")<block.indexOf("EPOCH.release(this)"));assertTrue(block.contains("if(rootAcceptanceEntered&&candidate==null)resources=false"));assertTrue(block.contains("if(released){if(rootEpochHeld)"));assertTrue(r.contains("business.deadline(now)"));}
 @Test public void fixturePublicationNeverAcceptsLiveEvidence()throws Exception{String r=source("CaptureSessionRuntime.java");String block=r.substring(r.indexOf("static RootPublication fixturePreflight("),r.indexOf("RootCaptureIntent intent(){"));assertTrue(block.contains("intent.live()"));assertTrue(block.contains("clean.liveTransport()"));assertTrue(block.contains("observation.capture.owner!=request"));assertFalse(block.contains("new LiveClick"));}
 @Test public void disclosedWholeScreenAndUncertainAbortAreAccurate()throws Exception{String u=source("RootCaptureUi.java");assertTrue(u.contains("整屏"));assertTrue(u.contains("通知"));assertTrue(u.contains("不录音"));assertTrue(u.contains("硬中止"));assertTrue(u.contains("23:00"));assertTrue(u.contains("00:30"));}
 @Test public void rootMarkerLowScoreIsDiagnosticNotIdentity(){var d=MaaRecognizer.rootMarkers(List.of(new FrameStructureEvidence.Line("Bing",0,0,10,10,.30),new FrameStructureEvidence.Line("private irrelevant text",0,10,10,10,1)));assertTrue(d.summary().contains("rootPageMarkerState=UNKNOWN"));assertTrue(d.summary().contains("targetIdentity=UNPROVEN"));assertFalse(d.summary().contains("private irrelevant text"));assertEquals(1,d.markers().stream().filter(x->x.marker()==MaaRecognizer.RootMarker.BING).findFirst().get().candidates());}
 @Test public void rootMarkerCountsSameBatchAndRejectsInvalidConfidence(){var d=MaaRecognizer.rootMarkers(List.of(new FrameStructureEvidence.Line("Rewards",0,0,10,10,.9),new FrameStructureEvidence.Line("Bing",0,10,10,10,Double.NaN),new FrameStructureEvidence.Line("更多活动",0,20,10,10,1.2)));assertEquals(3,d.nativeRows());assertEquals(1,d.markers().stream().mapToInt(MaaRecognizer.RootMarkerCount::highConfidence).sum());assertTrue(d.summary().contains("DIAGNOSTIC_ONLY"));assertFalse(d.summary().contains("更多活动"));}
 @Test public void sharedHiddenLeaseRevokesCurrentPhaseNotOnlyPublishedFirst()throws Exception{String r=source("CaptureSessionRuntime.java"),a=source("DormantCaptureConfirmationActivity.java");assertTrue(r.contains("rootNavigationRevoked(){if(returnReadIntent!=null){activity.returnReadVisibilityRevoked(returnReadIntent);return;}if(boundedIntent!=null)activity.boundedVisibilityRevoked(boundedIntent);else if(seriesIntent!=null)activity.seriesVisibilityRevoked(seriesIntent);else activity.rootVisibilityRevoked(rootIntent);}"));assertTrue(a.contains("CaptureSessionRuntime active=runtime;"));assertTrue(a.contains("rootIntent==exactIntent&&active!=null&&active.isRoot()"));assertTrue(r.contains("rootVisibilityRevoked(){if(!reportFinal||!released||!rootPublished)cancel();}"));}
 @Test public void fixtureRunCannotReachLiveEntryOrLivePublication()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("if(business.fixtureOnly())throw new SecurityException"));assertTrue(r.contains("if(autonomousRun!=null&&autonomousRun.fixtureOnly())return null"));assertTrue(r.contains("phase==null||business==null||!business.fixtureOnly()"));}
}